import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.DTehG4Nr.js";const h=JSON.parse('{"title":"Depth Wallpaper","description":"","frontmatter":{},"headers":[],"relativePath":"features/depth-wallpaper.md","filePath":"features/depth-wallpaper.md"}'),n={name:"features/depth-wallpaper.md"};function s(l,e,p,i,d,c){return t(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="depth-wallpaper" tabindex="-1">Depth Wallpaper <a class="header-anchor" href="#depth-wallpaper" aria-label="Permalink to &quot;Depth Wallpaper&quot;">​</a></h1><p>The <strong>Depth Wallpaper</strong> effect creates a parallax-style layered look by splitting your wallpaper into a background and a foreground subject layer — giving the lockscreen a 3D depth appearance with your wallpaper&#39;s subject rendered in front of the clock.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>Weeabooify extracts the subject from your wallpaper using a background processing pipeline (via WorkManager), then renders two independent layers:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────┐</span></span>
<span class="line"><span>│   Foreground (subject)  │  ← rendered above clock</span></span>
<span class="line"><span>│        Clock / UI       │</span></span>
<span class="line"><span>│   Background (scene)    │  ← rendered behind everything</span></span>
<span class="line"><span>└─────────────────────────┘</span></span></code></pre></div><p>Changes are processed automatically whenever your wallpaper changes.</p><h2 id="scale-foreground-image" tabindex="-1">Scale Foreground Image <a class="header-anchor" href="#scale-foreground-image" aria-label="Permalink to &quot;Scale Foreground Image&quot;">​</a></h2><p><strong>Match to native device wallpaper</strong> — scales the extracted foreground subject to match the dimensions and positioning of your device&#39;s native wallpaper, so the subject aligns naturally without manual adjustments.</p><h2 id="custom-images" tabindex="-1">Custom Images <a class="header-anchor" href="#custom-images" aria-label="Permalink to &quot;Custom Images&quot;">​</a></h2><p>Override either layer with your own image instead of using the auto-extracted wallpaper:</p><ul><li><strong>Custom background image</strong> — replace the background layer with any image of your choice</li><li><strong>Custom foreground image</strong> — replace the extracted subject layer with your own image</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Using a custom foreground with a transparent PNG gives you full control over what appears in front of the clock, independent of your wallpaper.</p></div><h2 id="background-adjustments" tabindex="-1">Background Adjustments <a class="header-anchor" href="#background-adjustments" aria-label="Permalink to &quot;Background Adjustments&quot;">​</a></h2><p>Fine-tune the background layer&#39;s appearance:</p><ul><li><strong>Dim</strong> — darken the background to reduce visual noise behind the clock</li><li><strong>Blur</strong> — apply a frosted glass blur to the background layer</li></ul><h2 id="foreground-adjustments" tabindex="-1">Foreground Adjustments <a class="header-anchor" href="#foreground-adjustments" aria-label="Permalink to &quot;Foreground Adjustments&quot;">​</a></h2><p>Fine-tune the foreground subject layer&#39;s appearance:</p><ul><li><strong>Dim</strong> — add a darkening overlay over the foreground subject</li><li><strong>Blur</strong> — soften the foreground subject edges for a depth-of-field effect</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Depth Wallpaper processing runs via <strong>WorkManager</strong> and a broadcast, so extraction happens even when the Weeabooify app is not in the foreground.</p></div>`,19)])])}const g=a(n,[["render",s]]);export{h as __pageData,g as default};
